/** One talent as `data/talents/<class>.json` stores it (GENERATED by `scripts.wow_talents.build`). */
export interface TalentFileTalent {
  id: number;
  name: string;
  /** Row, 0 (top) to 6. */
  tier: number;
  /** Column, 0 to 3. */
  column: number;
  /** Icon file data id; 0 = no icon in the client. */
  icon: number;
  /** Each rank's evaluated tooltip; null = the Forever client doesn't have that rank yet. */
  ranks: (string | null)[];
  /** `[talent id, rank needed]` pairs (rank 1-based). */
  prereqs: number[][];
  /** No rank is in the Forever client yet, so the name is the Classic Era client's. */
  classicName?: boolean;
}
